function validatePhone(value) {
  // Phone is optional — only validate format if a value was entered
  if (!value.trim()) return null;

  const digitCount = (value.match(/\d/g) || []).length;
  const formatRe = /^\+?[\d\s\-(). ]{7,20}$/;

