  constructor(formEl) {
    this.form     = formEl;
    this.statusEl = document.getElementById('form-status');

    this.fields = [
      new FormField({
        inputId:  'full-name',
        errorId:  'full-name-error',
        validate: validateFullName,
      }),
      new FormField({
        inputId:  'email',
        errorId:  'email-error',
        validate: validateEmail,
      }),
      new FormField({
        inputId:  'phone',
        errorId:  'phone-error',
        validate: validatePhone,
      }),
    ];

