const fs = require('fs');

(async () => {
  const html = fs.readFileSync('index.html', 'utf8');
  const b = await chromium.launch();
  const page = await b.newPage();

  // Inline scripts in the HTML reference external form.js; serve everything
  await page.route('**/*', async (route) => {
    const url = route.request().url();
    if (url.endsWith('form.js')) {
      route.fulfill({ body: fs.readFileSync('form.js', 'utf8'), contentType: 'text/javascript' });
    } else if (url.endsWith('styles.css')) {
      route.fulfill({ body: fs.readFileSync('styles.css', 'utf8'), contentType: 'text/css' });
    } else {
      route.continue();
    }
  });

  await page.goto('about:blank');
  await page.setContent(html, { waitUntil: 'load' });
  await page.addScriptTag({ path: '/tmp/axe.min.js' });

  // Trigger the error state by clicking submit with empty fields
  await page.click('.submit-btn');
  await page.waitForTimeout(200);

  const r = await page.evaluate(async () => await window.axe.run());
  await b.close();

  const wcag = r.violations.filter(v => !v.tags.includes('best-practice'));
  const bp   = r.violations.filter(v =>  v.tags.includes('best-practice'));
