function validateFullName(value) {
  if (!value.trim()) {
    return 'Error: Full name is required.';
  }
  if (value.trim().length < 2) {
    return 'Error: Full name must be at least 2 characters.';
  }
  return null;
}

function validateEmail(value) {
  if (!value.trim()) {
    return 'Error: Email address is required.';
  }
  // Basic structural check; the browser's type="email" handles stricter parsing
  const emailRe = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
  if (!emailRe.test(value.trim())) {
    return 'Error: Enter a valid email address, like name@example.com.';
  }
  return null;
}

function validatePhone(value) {
  // Phone is optional — only validate format if a value was entered
  if (!value.trim()) return null;

  const digitCount = (value.match(/\d/g) || []).length;
  const formatRe = /^\+?[\d\s\-(). ]{7,20}$/;

  if (!formatRe.test(value.trim()) || digitCount < 7) {
    return 'Error: Enter a valid phone number, like 555-123-4567 or +1 (555) 123-4567.';
  }
  return null;
}

// ─── FormField component ──────────────────────────────────────────────────────
//
// Encapsulates a single field's DOM references, validation, and state.
// Mirrors a React component's concern boundary without a framework.

class FormField {
  constructor({ inputId, errorId, validate }) {
    this.input    = document.getElementById(inputId);
    this.errorEl  = document.getElementById(errorId);
    this._validate = validate;
    this._touched  = false;

    this._bindEvents();
  }

  // Validate on blur (marks the field as touched) and live-validate on
  // subsequent input events so errors clear as soon as the user fixes them.
  _bindEvents() {
    this.input.addEventListener('blur', () => {
      this._touched = true;
      this._runValidation();
    });

    this.input.addEventListener('input', () => {
      if (this._touched) this._runValidation();
    });
  }

  _runValidation() {
    const error = this._validate(this.input.value);
    if (error) {
      this._setError(error);
      return false;
    }
    this._clearError();
    return true;
  }

  _setError(message) {
    this.input.setAttribute('aria-invalid', 'true');
    this.errorEl.textContent = message;
    this.errorEl.classList.add('visible');
  }

  _clearError() {
    this.input.removeAttribute('aria-invalid');
    this.errorEl.textContent = '';
    this.errorEl.classList.remove('visible');
  }

  /** Called by ContactForm on submit: marks touched, validates, returns valid. */
  submit() {
    this._touched = true;
    return this._runValidation();
  }

  reset() {
    this._touched = false;
    this._clearError();
  }

  focus() {
    this.input.focus();
  }
}

// ─── ContactForm component ────────────────────────────────────────────────────
//
// Owns the collection of FormField instances, handles submit, and manages
// the top-level status live region.

class ContactForm {
  constructor(formEl) {
    this.form     = formEl;
    this.statusEl = document.getElementById('form-status');

    this.fields = [
      new FormField({
        inputId:  'full-name',
        errorId:  'full-name-error',
        validate: validateFullName,
      }),
      new FormField({
        inputId:  'email',
        errorId:  'email-error',
        validate: validateEmail,
      }),
      new FormField({
        inputId:  'phone',
        errorId:  'phone-error',
        validate: validatePhone,
      }),
    ];

    this.form.addEventListener('submit', (e) => this._handleSubmit(e));
  }

  _handleSubmit(e) {
    e.preventDefault();

    const results = this.fields.map((field) => field.submit());
    const firstInvalidIndex = results.indexOf(false);

    if (firstInvalidIndex !== -1) {
      // Move focus to the first invalid field so AT announces the error via
      // aria-describedby; do NOT also use role="alert" here — pick one channel.
      this.fields[firstInvalidIndex].focus();
      // Clear any lingering success message
      this.statusEl.textContent = '';
      return;
    }

    // All fields valid — simulate a successful submission
    this.form.reset();
    this.fields.forEach((field) => field.reset());

    // Announce success via the pre-rendered role="status" live region
    this.statusEl.textContent =
      "Your message has been sent. We\u2019ll get back to you within 24 hours.";
  }
}

// ─── Bootstrap ───────────────────────────────────────────────────────────────

document.addEventListener('DOMContentLoaded', () => {
  const formEl = document.getElementById('contact-form');
  if (formEl) new ContactForm(formEl);
});
